/** Flow-control credit from the worklet to the worker. */
export interface StreamCredit {
  /** Stream id, named in stream messages. */
  streamId: number;
  /** Stream epoch; a restart bumps it, so older-epoch messages are stale. */
  epoch: number;
  /** Sample frames the worklet has consumed. */
  consumedFrames: number;
  /** Chunk buffers returned to the worker. */
  returnedBuffers: number;
}

export const STREAM_CREDIT_FIXED_END = 32;

export function writeStreamCredit(view: DataView, off: number, rec: StreamCredit): number {
  view.setUint32(off + 16, rec.streamId, true);
  view.setUint32(off + 20, rec.epoch, true);
  view.setUint32(off + 24, rec.consumedFrames, true);
  view.setUint32(off + 28, rec.returnedBuffers, true);
  let cur = off + 32;
  return cur - off;
}

function _readStreamCredit(view: DataView, off: number, limit: number): [StreamCredit, number] {
  if (off + 32 > limit) throw new WireError(ErrorCode.TRUNCATED, "StreamCredit: truncated");
  const streamId = view.getUint32(off + 16, true);
  const epoch = view.getUint32(off + 20, true);
  const consumedFrames = view.getUint32(off + 24, true);
  const returnedBuffers = view.getUint32(off + 28, true);
  let cur = off + 32;
  return [{ streamId, epoch, consumedFrames, returnedBuffers }, cur - off];
}

export function readStreamCredit(view: DataView, off: number): StreamCredit {
  const limit = view.byteLength;
  return _readStreamCredit(view, off, limit)[0];
}

/** the writer dropped records this batch */
export const REPLAY_FLAGS_OVERFLOWED = 0x1;
/** first chunk of a REPLAY (begins with RESET) */
export const REPLAY_FLAGS_FIRST_CHUNK = 0x2;
/** last chunk of a REPLAY */
export const REPLAY_FLAGS_LAST_CHUNK = 0x4;
/** loop the clip */
export const PLAY_FLAGS_LOOP = 0x1;
/** a stream voice (STREAM_OPEN), not a clip */
export const PLAY_FLAGS_STREAM = 0x2;
/** report the playhead in STATUS */
export const PLAY_FLAGS_WANTS_PLAYHEAD = 0x4;
/** mixed (1) or virtual (0) */
export const PLAY_FLAGS_MIXED = 0x8;
/** spatialised; the panner applies */
export const PLAY_FLAGS_SPATIAL = 0x10;
/** 0 equal-power, 1 HRTF, 2 bed (ADR 0162 C1: the bus's bed slot, equal-power without one), 3 reserved; spatial voices only */
export const PLAY_FLAGS_PANNER_SHIFT = 5;
export const PLAY_FLAGS_PANNER_MASK = 0x60;
/** a B-format clip or stream voice of 4, 9 or 16 channels (ADR 0162 C1); spatial, panner and dir are ignored; read from PLAY only */
export const PLAY_FLAGS_AMBISONIC = 0x80;
/** the voice starts with its fade ramp at 0, so an incoming stem is silent without touching gain; a stamped FADE to 1 opens it (ADR 0166 M4, API section 4.1); read from PLAY only */
export const PLAY_FLAGS_FADE_ZERO = 0x100;
/** start a voice; does not ramp */
export interface Play {
  voiceId: number;
  frameOffset: number;
  /** clip id */
  clip: number;
  /** bus index */
  bus: number;
  flags: number;
  group: number;
  reserved: number;
  gain: number;
  pitch: number;
  dirX: number;
  dirY: number;
  dirZ: number;
  lpHz: number;
  score: number;
  startOffsetFrames: number;
}

export const PLAY_FIXED_END = 56;

export function writePlay(view: DataView, off: number, rec: Play): number {
  view.setUint32(off + 12, rec.clip, true);
  view.setUint16(off + 16, rec.bus, true);
  view.setUint16(off + 18, rec.flags, true);
  view.setUint16(off + 20, rec.group, true);
  view.setUint16(off + 22, rec.reserved, true);
  view.setFloat32(off + 24, rec.gain, true);
  view.setFloat32(off + 28, rec.pitch, true);
  view.setFloat32(off + 32, rec.dirX, true);
  view.setFloat32(off + 36, rec.dirY, true);
  view.setFloat32(off + 40, rec.dirZ, true);
  view.setFloat32(off + 44, rec.lpHz, true);
  view.setFloat32(off + 48, rec.score, true);
  view.setUint32(off + 52, rec.startOffsetFrames, true);
  let cur = off + 56;
  const total = cur - off;
  if (total % 4 !== 0 || total / 4 > 0xffff) throw new WireError(ErrorCode.OVERSIZE, "Play: record too long");
  view.setUint16(off + 0, 1, true);
  view.setUint16(off + 2, total / 4, true);
  view.setUint32(off + 4, rec.voiceId, true);
  view.setUint32(off + 8, rec.frameOffset, true);
  return cur - off;
}

function _readPlay(view: DataView, off: number, limit: number): [Play, number] {
  if (off + 56 > limit) throw new WireError(ErrorCode.TRUNCATED, "Play: truncated");
  const clip = view.getUint32(off + 12, true);
  const bus = view.getUint16(off + 16, true);
  const flags = view.getUint16(off + 18, true);
  const group = view.getUint16(off + 20, true);
  const reserved = view.getUint16(off + 22, true);
  const gain = view.getFloat32(off + 24, true);
  const pitch = view.getFloat32(off + 28, true);
  const dirX = view.getFloat32(off + 32, true);
  const dirY = view.getFloat32(off + 36, true);
  const dirZ = view.getFloat32(off + 40, true);
  const lpHz = view.getFloat32(off + 44, true);
  const score = view.getFloat32(off + 48, true);
  const startOffsetFrames = view.getUint32(off + 52, true);
  let cur = off + 56;
  if (cur > limit) throw new WireError(ErrorCode.MALFORMED, "Play: malformed");
  cur = limit;
  const voiceId = view.getUint32(off + 4, true);
  const frameOffset = view.getUint32(off + 8, true);
  return [{ voiceId, frameOffset, clip, bus, flags, group, reserved, gain, pitch, dirX, dirY, dirZ, lpHz, score, startOffsetFrames }, cur - off];
}

export function readPlay(view: DataView, off: number): Play {
  if (off + 12 > view.byteLength) throw new WireError(ErrorCode.TRUNCATED, "Play: truncated");
  if (view.getUint16(off + 0, true) !== 1) throw new WireError(ErrorCode.MALFORMED, "Play: wrong opcode");
  const limit = off + view.getUint16(off + 2, true) * 4;
  if (limit > view.byteLength) throw new WireError(ErrorCode.TRUNCATED, "Play: truncated");
  return _readPlay(view, off, limit)[0];
}

/** 0 linear, 1 sCurve, 2 equalPowerIn, 3 equalPowerOut (FadeLaw); 4-7 reserved */
export const STOP_SHAPE_LAW_SHIFT = 0;
export const STOP_SHAPE_LAW_MASK = 0x7;
/** start phase of the curve as u0.16: value / 65,536 */
export const STOP_SHAPE_START_PHASE_SHIFT = 16;
export const STOP_SHAPE_START_PHASE_MASK = 0xffff0000;
/** stop a voice */
export interface Stop {
  voiceId: number;
  frameOffset: number;
  /** 0 is now */
  fadeFrames: number;
  reason: number;
  /** law and start phase of the ramp (envelope 1.2); a record without the word reads 0 */
  shape?: number;
}

export const STOP_FIXED_END = 24;

export function writeStop(view: DataView, off: number, rec: Stop): number {
  view.setUint32(off + 12, rec.fadeFrames, true);
  view.setUint32(off + 16, rec.reason, true);
  view.setUint32(off + 20, (rec.shape ?? 0), true);
  let cur = off + 24;
  const total = cur - off;
  if (total % 4 !== 0 || total / 4 > 0xffff) throw new WireError(ErrorCode.OVERSIZE, "Stop: record too long");
  view.setUint16(off + 0, 2, true);
  view.setUint16(off + 2, total / 4, true);
  view.setUint32(off + 4, rec.voiceId, true);
  view.setUint32(off + 8, rec.frameOffset, true);
  return cur - off;
}

function _readStop(view: DataView, off: number, limit: number): [Stop, number] {
  if (off + 20 > limit) throw new WireError(ErrorCode.TRUNCATED, "Stop: truncated");
  const fadeFrames = view.getUint32(off + 12, true);
  const reason = view.getUint32(off + 16, true);
  const shape = off + 24 <= limit ? view.getUint32(off + 20, true) : 0;
  let cur = Math.min(off + 24, limit);
  if (cur > limit) throw new WireError(ErrorCode.MALFORMED, "Stop: malformed");
  cur = limit;
  const voiceId = view.getUint32(off + 4, true);
  const frameOffset = view.getUint32(off + 8, true);
  return [{ voiceId, frameOffset, fadeFrames, reason, shape }, cur - off];
}

export function readStop(view: DataView, off: number): Stop {
  if (off + 12 > view.byteLength) throw new WireError(ErrorCode.TRUNCATED, "Stop: truncated");
  if (view.getUint16(off + 0, true) !== 2) throw new WireError(ErrorCode.MALFORMED, "Stop: wrong opcode");
  const limit = off + view.getUint16(off + 2, true) * 4;
  if (limit > view.byteLength) throw new WireError(ErrorCode.TRUNCATED, "Stop: truncated");
  return _readStop(view, off, limit)[0];
}

/** gain */
export const SET_PARAMS_MASK_GAIN = 0x1;
/** pitch */
export const SET_PARAMS_MASK_PITCH = 0x2;
/** dirX, dirY, dirZ */
export const SET_PARAMS_MASK_DIR = 0x4;
/** lpHz */
export const SET_PARAMS_MASK_LP_HZ = 0x8;
/** score */
export const SET_PARAMS_MASK_SCORE = 0x10;
/** bus */
export const SET_PARAMS_MASK_BUS = 0x20;
/** flags (the panner bits) */
export const SET_PARAMS_MASK_FLAGS = 0x40;
/** loop the clip */
export const SET_PARAMS_FLAGS_LOOP = 0x1;
/** a stream voice (STREAM_OPEN), not a clip */
export const SET_PARAMS_FLAGS_STREAM = 0x2;
/** report the playhead in STATUS */
export const SET_PARAMS_FLAGS_WANTS_PLAYHEAD = 0x4;
/** mixed (1) or virtual (0) */
export const SET_PARAMS_FLAGS_MIXED = 0x8;
/** spatialised; the panner applies */
export const SET_PARAMS_FLAGS_SPATIAL = 0x10;
/** 0 equal-power, 1 HRTF, 2 bed (ADR 0162 C1: the bus's bed slot, equal-power without one), 3 reserved; spatial voices only */
export const SET_PARAMS_FLAGS_PANNER_SHIFT = 5;
export const SET_PARAMS_FLAGS_PANNER_MASK = 0x60;
/** a B-format clip or stream voice of 4, 9 or 16 channels (ADR 0162 C1); spatial, panner and dir are ignored; read from PLAY only */
export const SET_PARAMS_FLAGS_AMBISONIC = 0x80;
/** the voice starts with its fade ramp at 0, so an incoming stem is silent without touching gain; a stamped FADE to 1 opens it (ADR 0166 M4, API section 4.1); read from PLAY only */
export const SET_PARAMS_FLAGS_FADE_ZERO = 0x100;
/** 0 linear, 1 sCurve, 2 equalPowerIn, 3 equalPowerOut (FadeLaw); 4-7 reserved */
export const SET_PARAMS_SHAPE_LAW_SHIFT = 0;
export const SET_PARAMS_SHAPE_LAW_MASK = 0x7;
/** start phase of the curve as u0.16: value / 65,536 */
export const SET_PARAMS_SHAPE_START_PHASE_SHIFT = 16;
export const SET_PARAMS_SHAPE_START_PHASE_MASK = 0xffff0000;
/** set voice parameters; ramps over rampFrames */
export interface SetParams {
  voiceId: number;
  frameOffset: number;
  mask: number;
  gain: number;
  pitch: number;
  dirX: number;
  dirY: number;
  dirZ: number;
  /** low-pass cutoff, applied to every voice below LP_TOP (ADR 0162 §4.1), ramped in log-Hz */
  lpHz: number;
  score: number;
  bus: number;
  rampFrames: number;
  /** only the panner bits are read */
  flags: number;
  /** law and start phase of the ramp (envelope 1.2); a record without the word reads 0 */
  shape?: number;
}

export const SET_PARAMS_FIXED_END = 60;

export function writeSetParams(view: DataView, off: number, rec: SetParams): number {
  view.setUint32(off + 12, rec.mask, true);
  view.setFloat32(off + 16, rec.gain, true);
  view.setFloat32(off + 20, rec.pitch, true);
  view.setFloat32(off + 24, rec.dirX, true);
  view.setFloat32(off + 28, rec.dirY, true);
  view.setFloat32(off + 32, rec.dirZ, true);
  view.setFloat32(off + 36, rec.lpHz, true);
  view.setFloat32(off + 40, rec.score, true);
  view.setUint32(off + 44, rec.bus, true);
  view.setUint32(off + 48, rec.rampFrames, true);
  view.setUint32(off + 52, rec.flags, true);
  view.setUint32(off + 56, (rec.shape ?? 0), true);
  let cur = off + 60;
  const total = cur - off;
  if (total % 4 !== 0 || total / 4 > 0xffff) throw new WireError(ErrorCode.OVERSIZE, "SetParams: record too long");
  view.setUint16(off + 0, 3, true);
  view.setUint16(off + 2, total / 4, true);
  view.setUint32(off + 4, rec.voiceId, true);
  view.setUint32(off + 8, rec.frameOffset, true);
  return cur - off;
}

function _readSetParams(view: DataView, off: number, limit: number): [SetParams, number] {
  if (off + 56 > limit) throw new WireError(ErrorCode.TRUNCATED, "SetParams: truncated");
  const mask = view.getUint32(off + 12, true);
  const gain = view.getFloat32(off + 16, true);
  const pitch = view.getFloat32(off + 20, true);
  const dirX = view.getFloat32(off + 24, true);
  const dirY = view.getFloat32(off + 28, true);
  const dirZ = view.getFloat32(off + 32, true);
  const lpHz = view.getFloat32(off + 36, true);
  const score = view.getFloat32(off + 40, true);
  const bus = view.getUint32(off + 44, true);
  const rampFrames = view.getUint32(off + 48, true);
  const flags = view.getUint32(off + 52, true);
  const shape = off + 60 <= limit ? view.getUint32(off + 56, true) : 0;
  let cur = Math.min(off + 60, limit);
  if (cur > limit) throw new WireError(ErrorCode.MALFORMED, "SetParams: malformed");
  cur = limit;
  const voiceId = view.getUint32(off + 4, true);
  const frameOffset = view.getUint32(off + 8, true);
  return [{ voiceId, frameOffset, mask, gain, pitch, dirX, dirY, dirZ, lpHz, score, bus, rampFrames, flags, shape }, cur - off];
}

export function readSetParams(view: DataView, off: number): SetParams {
  if (off + 12 > view.byteLength) throw new WireError(ErrorCode.TRUNCATED, "SetParams: truncated");
  if (view.getUint16(off + 0, true) !== 3) throw new WireError(ErrorCode.MALFORMED, "SetParams: wrong opcode");
  const limit = off + view.getUint16(off + 2, true) * 4;
  if (limit > view.byteLength) throw new WireError(ErrorCode.TRUNCATED, "SetParams: truncated");
  return _readSetParams(view, off, limit)[0];
}

/** stop the voice at the end of the fade */
export const FADE_FLAGS_STOP_AT_END = 0x1;
/** 0 linear, 1 sCurve, 2 equalPowerIn, 3 equalPowerOut (FadeLaw); 4-7 reserved */
export const FADE_SHAPE_LAW_SHIFT = 0;
export const FADE_SHAPE_LAW_MASK = 0x7;
/** start phase of the curve as u0.16: value / 65,536 */
export const FADE_SHAPE_START_PHASE_SHIFT = 16;
export const FADE_SHAPE_START_PHASE_MASK = 0xffff0000;
/** fade a voice's gain to target */
export interface Fade {
  voiceId: number;
  frameOffset: number;
  target: number;
  frames: number;
  flags: number;
  /** law and start phase of the ramp (envelope 1.2); a record without the word reads 0 */
  shape?: number;
}

export const FADE_FIXED_END = 28;

export function writeFade(view: DataView, off: number, rec: Fade): number {
  view.setFloat32(off + 12, rec.target, true);
  view.setUint32(off + 16, rec.frames, true);
  view.setUint32(off + 20, rec.flags, true);
  view.setUint32(off + 24, (rec.shape ?? 0), true);
  let cur = off + 28;
  const total = cur - off;
  if (total % 4 !== 0 || total / 4 > 0xffff) throw new WireError(ErrorCode.OVERSIZE, "Fade: record too long");
  view.setUint16(off + 0, 4, true);
  view.setUint16(off + 2, total / 4, true);
  view.setUint32(off + 4, rec.voiceId, true);
  view.setUint32(off + 8, rec.frameOffset, true);
  return cur - off;
}

function _readFade(view: DataView, off: number, limit: number): [Fade, number] {
  if (off + 24 > limit) throw new WireError(ErrorCode.TRUNCATED, "Fade: truncated");
  const target = view.getFloat32(off + 12, true);
  const frames = view.getUint32(off + 16, true);
  const flags = view.getUint32(off + 20, true);
  const shape = off + 28 <= limit ? view.getUint32(off + 24, true) : 0;
  let cur = Math.min(off + 28, limit);
  if (cur > limit) throw new WireError(ErrorCode.MALFORMED, "Fade: malformed");
  cur = limit;
  const voiceId = view.getUint32(off + 4, true);
  const frameOffset = view.getUint32(off + 8, true);
  return [{ voiceId, frameOffset, target, frames, flags, shape }, cur - off];
}

export function readFade(view: DataView, off: number): Fade {
  if (off + 12 > view.byteLength) throw new WireError(ErrorCode.TRUNCATED, "Fade: truncated");
  if (view.getUint16(off + 0, true) !== 4) throw new WireError(ErrorCode.MALFORMED, "Fade: wrong opcode");
  const limit = off + view.getUint16(off + 2, true) * 4;
  if (limit > view.byteLength) throw new WireError(ErrorCode.TRUNCATED, "Fade: truncated");
  return _readFade(view, off, limit)[0];
}

